sp_widget.client_script:
api.controller = function($location) {
  var c = this;

  c.search = function() {
    if (c.keywords) {
      $location.search({
        id: 'search',
        q: c.keywords,
        t: 'case_point_search' // Optional: specialized search source
      });
    }
  };

  c.checkEnter = function(event) {
    if (event.which === 13) {
      c.search();
    }
  };
};

sp_widget.css:
.hero-container {
  background: linear-gradient(135deg, $brand-primary 0%, darken($brand-primary, 10%) 100%);
  padding: 80px 0;
  color: #fff;
  margin-bottom: 30px;
}
.hero-title {
  font-weight: 700;
  font-size: 42px;
  margin-bottom: 15px;
  text-shadow: 0 2px 4px rgba(0,0,0,0.2);
}
.hero-subtitle {
  font-size: 18px;
  opacity: 0.9;
  margin-bottom: 40px;
}
.search-box {
  max-width: 600px;
  margin: 0 auto;
  position: relative;
}
.search-box .form-control {
  border-radius: 30px;
  padding-right: 50px;
  border: none;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  height: 50px;
}
.btn-search {
  position: absolute;
  right: 5px;
  top: 5px;
  height: 40px;
  width: 40px;
  border-radius: 50%;
  background-color: $brand-secondary;
  color: $brand-primary;
  border: none;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.btn-search:hover {
  background-color: lighten($brand-secondary, 10%);
}
